const items = $input.all();

return items.map((item, index) => {
  // Find the original validated inquiry using item linking.
  let source;

  try {
    source = $('Validate Customer Inquiry')
      .itemMatching(index).json;
  } catch (error) {
    throw new Error(
      `Cannot match AI result ${index} to its original inquiry. ` +
      `Check item linking in the AI Agent and Insert row nodes.`
    );
  }

  const raw = item.json.output;

  let ai;

  try {
    ai = typeof raw === 'string'
      ? JSON.parse(
          raw.replace(/```(?:json)?|```/g, '').trim()
        )
      : raw;

    const validCategories = [
      'ORDER', 'DELIVERY', 'RETURN',
      'COMPLAINT', 'GENERAL'
    ];

    const validPriorities = ['HIGH', 'MEDIUM', 'LOW'];

    if (
      !ai ||
      !validCategories.includes(ai.category) ||
      !validPriorities.includes(ai.priority) ||
      typeof ai.summary !== 'string' ||
      typeof ai.suggested_reply !== 'string' ||
      !ai.summary.trim() ||
      !ai.suggested_reply.trim()
    ) {
      throw new Error('Invalid AI response');
    }

  } catch (error) {
    ai = {
      category: 'GENERAL',
      priority: 'HIGH',
      summary: 'AI output requires manual review',
      suggested_reply: '',
      processing_error: error.message
    };
  }

  return {
    json: {
      inquiry_id: source.inquiry_id,
      customer_name: source.customer_name,
      email: source.email,
      message: source.message,
      inquiry_type: source.inquiry_type,
      submitted_at: source.submitted_at,

      category: ai.category,
      priority: ai.priority,
      summary: ai.summary,
      suggested_reply: ai.suggested_reply,

      status: ai.processing_error
        ? 'Manual Review Required'
        : 'Pending Review',

      processed_at: new Date().toISOString(),

      ...(ai.processing_error
        ? { processing_error: ai.processing_error }
        : {})
    },
    pairedItem: index
  };
});

const items = $input.all();

return items.map((item) => {
  // Normalize incoming Google Sheets column names
  const data = Object.fromEntries(
    Object.entries(item.json).map(([key, value]) => [
      key.trim(),
      value
    ])
  );

  const customerName = String(data['Customer Name'] ?? '').trim();
  const email = String(data['Email Address'] ?? '').trim().toLowerCase();
  const inquiryType = String(data['Inquiry Type'] ?? '').trim();
  const message = String(data['Your Message'] ?? '').trim();
  const timestamp = String(data['Timestamp'] ?? '').trim();

  const errors = [];

  if (!customerName) {
    errors.push('Missing customer name');
  }

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.push('Invalid email address');
  }

  if (!message) {
    errors.push('Missing customer message');
  }

  if (!timestamp) {
    errors.push('Missing submission timestamp');
  }

  const source = JSON.stringify([
    timestamp,
    email,
    customerName,
    inquiryType,
    message
  ]);

  let h1 = 0x811c9dc5;
  let h2 = 0x811c9dc5;

  for (let i = 0; i < source.length; i++) {
    const c = source.charCodeAt(i);

    h1 = Math.imul(h1 ^ c, 0x01000193);
    h2 = Math.imul(h2 ^ (c + i), 0x01000193);
  }

  const id = [h1, h2]
    .map(h => (h >>> 0).toString(16).padStart(8, '0'))
    .join('')
    .toUpperCase();

  return {
    json: {
      ...data,
      inquiry_id: `INQ-${id}`,
      customer_name: customerName,
      email,
      inquiry_type: inquiryType,
      message,
      submitted_at: timestamp,
      validation_status: errors.length ? 'INVALID' : 'VALID',
      validation_errors: errors
    }
  };
});

const registryItems = $input.all();
const classifiedItems = $('Code in JavaScript').all();

const inquiryMap = new Map();

for (const item of classifiedItems) {
  const data = item.json;

  if (!data.inquiry_id) {
    throw new Error('Missing inquiry_id in AI output');
  }

  inquiryMap.set(data.inquiry_id, data);
}

return registryItems.map((item, index) => {
  const registry = item.json;
  const original = inquiryMap.get(registry.inquiry_id);

  if (!original) {
    throw new Error(
      `No matching AI data for ${registry.inquiry_id}`
    );
  }

  return {
    json: {
      ...original,
      registry_id: registry.id,
      processing_status: registry.processing_status,
      notification_status: registry.notification_status
    },
    pairedItem: index
  };
});

const registryItems = $input.all();

const originalItems = $('Restore Inquiry Data').all();

const inquiryMap = new Map(
  originalItems.map(item => [
    item.json.inquiry_id,
    item.json
  ])
);

return registryItems.map((item, index) => {
  const registry = item.json;

  const original = inquiryMap.get(
    registry.inquiry_id
  );

  if (!original) {
    throw new Error(
      `Original inquiry data not found: ${registry.inquiry_id}`
    );
  }

  return {
    json: {
      ...original,
      notification_status: registry.notification_status,
      registry_id: registry.id
    },
    pairedItem: index
  };
});

